/*
 * A155777  Primes with largest digit prime.
 * https://oeis.org/A155777
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 29, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime, largest_digit_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by iterating over primes and selecting those whose largest decimal
   digit is one of 2, 3, 5 or 7. */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime.h"
#include "../utils/largest_digit_prime.h"

/* a(n) : return the n‑th term (1‑based) of the sequence   */
seq_t a(idx_t n)
{
    /* static state: cache of found terms, number of terms stored,
       next candidate to test, and cache capacity */
    static seq_t *cache          = NULL; /* array of terms */
    static size_t cache_size     = 0;     /* how many terms stored */
    static size_t cache_capacity = 0;     /* allocated size of cache */
    static uint64_t next_candidate = 2;   /* next integer to test */

    if (n == 0)                 /* offset is 1, so a(0) is undefined */
        return 0;

    /* Grow the cache until it contains at least n terms */
    while (cache_size < (size_t)n) {
        /* Check whether the current candidate is prime */
        if (is_prime((idx_t)next_candidate)) {
            /* If its largest digit is prime, store it */
            if (largest_digit_prime((seq_t)next_candidate)) {
                /* Ensure enough space in the cache */
                if (cache_size == cache_capacity) {
                    size_t new_cap = cache_capacity ? cache_capacity * 2 : 8;
                    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                    if (!tmp) { /* allocation failed – return 0 */
                        free(cache);
                        cache = NULL;
                        return 0;
                    }
                    cache = tmp;
                    cache_capacity = new_cap;
                }
                cache[cache_size++] = (seq_t)next_candidate;
            }
        }

        /* Advance to the next candidate:
           test 2, then 3, and afterwards only odd numbers. */
        if (next_candidate == 2)
            next_candidate = 3;
        else
            next_candidate += 2;
    }

    return cache[(size_t)n - 1];
}
